int gladLoaderLoadVulkan(VkInstance instance, VkPhysicalDevice physicalDevice, VkDevice device) {
	(void)instance; (void)physicalDevice; (void)device;
	return 0;
}
void gladLoaderUnloadVulkan(void) {}

// GLFW's Vulkan surface entry point. The desktop build gets this from GLFW; here
// the shim header declares it and this definition satisfies the linker.
// Reaching it would mean vulkanTestingMode got enabled, which never happens on
// the GLES renderer.
int glfwCreateWindowSurface(VkInstance instance, void* window, const void* allocator, VkSurfaceKHR* surface) {
	(void)instance; (void)window; (void)allocator; (void)surface;
	return VK_ERROR_INITIALIZATION_FAILED;
}

